public static string Objective(MissionObjective objective) {
    if (objective.Type == 7) return "Help close a realm by reaching 100% Realm Score, then enter Oryx's Castle when the realm closes.";
    if (objective.Type == 2) return "Defeat enemies while playing an eligible character. Only progress confirmed by the game is counted.";
    if (objective.Type == 15) return "Earn experience while playing an eligible character.";
    if (objective.Type == 1 && Encounters.TryGetValue(objective.Target, out string encounters)) return "Targets and realm locations: " + encounters;
    if (objective.Type == 1 && objective.Target.IndexOf("vortex", StringComparison.OrdinalIgnoreCase) >= 0) return "Defeat Wind Vortexes inside dungeons; realm encounters do not count for this target.";
    string[] dungeons = MissionTargets.Dungeons(objective);
    return string.Join(Environment.NewLine, dungeons.Select(d => d + ": " + Dungeon(d)));
}
public static string Dungeon(string name) {
    switch ((name ?? "").ToLowerInvariant()) {
        case "oryx's sanctuary": return "Close the realm, clear Oryx's Castle and Oryx's Chamber, open Wine Cellar with a Wine Cellar Incantation, then use Helmet, Shield, and Sword Runes after Oryx dies.";
        case "the void": case "void": return "Enter Lost Halls and defeat the Marble Colossus; use a Vial of Pure Darkness to open The Void. " + MissionTargets.Location("Lost Halls");
        case "cultist hideout": return "Enter Lost Halls, collect the five flames, and enter the Cultist Hideout portal. " + MissionTargets.Location("Lost Halls");
        case "crystal cavern": return "Continue through Fungal Cavern after defeating the Crystal Worm Mother. " + MissionTargets.Location("Fungal Cavern");
        case "oryx's castle": return "Entered after the realm reaches 100% score and closes. Clear the castle to reach Stone Guardians and Janus.";
        case "oryx's chamber": return "Clear Oryx's Castle and the Stone Guardians to enter Oryx's Chamber.";
        case "wine cellar": return "Use a Wine Cellar Incantation after defeating Oryx in Oryx's Chamber.";
        default: return MissionTargets.Location(name);
    }
}
